import { InsufficientStockError, ValidationError } from '../errors/DomainError';

/** Catalogue product together with the quantity currently available to reserve. */
export class Product {
  private constructor(
    readonly id: string,
    readonly name: string,
    private available: number,
  ) {}

  static create(id: string, name: string, initialStock: number): Product {
    if (!Number.isInteger(initialStock) || initialStock < 0) {
      throw new ValidationError(`Initial stock for product '${id}' must be a non-negative integer`);
    }
    return new Product(id, name, initialStock);
  }

  get stockLevel(): number {
    return this.available;
  }

  assertCanReserve(quantity: number): void {
    if (quantity > this.available) {
      throw new InsufficientStockError(this.id, quantity, this.available);
    }
  }

  reserve(quantity: number): void {
    this.assertCanReserve(quantity);
    this.available -= quantity;
  }

  release(quantity: number): void {
    this.available += quantity;
  }
}

